gmsg_error motor_motor_link_encode(const motor_motor_link_any_message* m, uint8_t* out, size_t capacity, size_t* written) {
    switch (m->kind) {
        case MOTOR_MOTOR_LINK_SET_SPEED: return motor_motor_link_encode_set_speed(&m->as.set_speed, out, capacity, written);
        case MOTOR_MOTOR_LINK_TELEMETRY: return motor_motor_link_encode_telemetry(&m->as.telemetry, out, capacity, written);
        case MOTOR_MOTOR_LINK_LOG: return motor_motor_link_encode_log(&m->as.log, out, capacity, written);
        default: break;
    }
    if (written) *written = 0;
    return GMSG_ERR_UNKNOWN_TYPE;
}

